package com.example.fqcapp.utils

import android.content.Context
import android.net.Uri
import android.util.Log
import org.videolan.libvlc.LibVLC
import org.videolan.libvlc.Media
import org.videolan.libvlc.MediaPlayer
import java.io.File

/**
 * VLC Player Manager for audio playback
 * Provides VLC-level codec support and advanced audio features
 */
class VLCPlayerManager(context: Context) {
    private val libVLC: LibVLC
    private var mediaPlayer: MediaPlayer? = null
    private var currentMedia: Media? = null

    // Callbacks
    var onProgressUpdate: ((Long) -> Unit)? = null
    var onCompletion: (() -> Unit)? = null
    var onError: ((String) -> Unit)? = null
    var onPlaying: (() -> Unit)? = null
    var onPaused: (() -> Unit)? = null
    var onStopped: (() -> Unit)? = null

    init {
        val options = ArrayList<String>().apply {
            // VLC options for better audio quality
            add("--aout=opensles") // Use OpenSL ES for better audio performance
            add("--audio-time-stretch") // Enable time stretching
            add("--live-caching=300") // Cache for streaming (not used for local files)
        }

        try {
            libVLC = LibVLC(context, options)
            Log.d("VLCPlayerManager", "✅ libVLC initialized successfully")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Failed to initialize libVLC", e)
            throw e
        }
    }

    /**
     * Play audio file
     */
    fun play(file: File) {
        try {
            release() // Release previous player if any

            val uri = Uri.fromFile(file)
            currentMedia = Media(libVLC, uri)

            mediaPlayer = MediaPlayer(libVLC).apply {
                setMedia(currentMedia)

                // Set up event listener
                setEventListener { event ->
                    when (event.type) {
                        MediaPlayer.Event.Playing -> {
                            Log.d("VLCPlayerManager", "▶️ Playing: ${file.name}")
                            onPlaying?.invoke()
                            // Start progress updates
                            updateProgress()
                        }
                        MediaPlayer.Event.Paused -> {
                            Log.d("VLCPlayerManager", "⏸️ Paused: ${file.name}")
                            onPaused?.invoke()
                        }
                        MediaPlayer.Event.Stopped -> {
                            Log.d("VLCPlayerManager", "⏹️ Stopped: ${file.name}")
                            onStopped?.invoke()
                        }
                        MediaPlayer.Event.EndReached -> {
                            Log.d("VLCPlayerManager", "✅ End reached: ${file.name}")
                            onCompletion?.invoke()
                        }
                        MediaPlayer.Event.EncounteredError -> {
                            val error = "VLC playback error"
                            Log.e("VLCPlayerManager", "❌ $error")
                            onError?.invoke(error)
                        }
                        else -> {
                            // Other events (Buffering, etc.)
                        }
                    }
                }

                play()
            }

            Log.d("VLCPlayerManager", "🎵 Started playing: ${file.name}")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error playing file: ${file.name}", e)
            onError?.invoke(e.message ?: "Unknown error")
        }
    }

    /**
     * Update playback progress (called periodically)
     * This should be called from a coroutine or timer
     */
    fun updateProgress() {
        mediaPlayer?.let { player ->
            try {
                if (player.isPlaying) {
                    val time = player.time
                    if (time >= 0) {
                        onProgressUpdate?.invoke(time)
                    }
                }
            } catch (e: Exception) {
                // Ignore errors during progress update
            }
        }
    }

    /**
     * Pause playback
     */
    fun pause() {
        try {
            mediaPlayer?.pause()
            Log.d("VLCPlayerManager", "⏸️ Paused")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error pausing", e)
        }
    }

    /**
     * Resume playback
     */
    fun resume() {
        try {
            mediaPlayer?.play()
            Log.d("VLCPlayerManager", "▶️ Resumed")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error resuming", e)
        }
    }

    /**
     * Stop playback
     */
    fun stop() {
        try {
            mediaPlayer?.stop()
            Log.d("VLCPlayerManager", "⏹️ Stopped")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error stopping", e)
        }
    }

    /**
     * Seek to position (in milliseconds)
     */
    fun seekTo(position: Long) {
        try {
            mediaPlayer?.time = position
            Log.d("VLCPlayerManager", "⏩ Seeked to: ${position}ms")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error seeking", e)
        }
    }

    /**
     * Get current playback position (in milliseconds)
     */
    fun getCurrentPosition(): Long {
        return try {
            mediaPlayer?.time ?: 0L
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error getting position", e)
            0L
        }
    }

    /**
     * Get total duration (in milliseconds)
     */
    fun getDuration(): Long {
        return try {
            mediaPlayer?.length ?: 0L
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error getting duration", e)
            0L
        }
    }

    /**
     * Check if currently playing
     */
    fun isPlaying(): Boolean {
        return try {
            mediaPlayer?.isPlaying ?: false
        } catch (e: Exception) {
            false
        }
    }

    /**
     * Set volume (0.0 to 1.0)
     * Note: VLC uses 0-200 range, we convert 0.0-1.0 to 0-200
     */
    fun setVolume(volume: Float) {
        try {
            val vlcVolume = (volume * 200).toInt().coerceIn(0, 200)
            mediaPlayer?.volume = vlcVolume
            Log.d("VLCPlayerManager", "🔊 Volume set to: ${(volume * 100).toInt()}% (VLC: $vlcVolume)")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error setting volume", e)
        }
    }

    /**
     * Set stereo volume (left and right channels)
     * Note: VLC doesn't support direct left/right volume, so we use balance
     */
    fun setStereoVolume(leftVolume: Float, rightVolume: Float) {
        try {
            // Calculate average volume
            val avgVolume = (leftVolume + rightVolume) / 2f
            setVolume(avgVolume)

            // Calculate balance (-1.0 = left, 0.0 = center, 1.0 = right)
            val balance = if (leftVolume + rightVolume > 0) {
                (rightVolume - leftVolume) / (leftVolume + rightVolume)
            } else {
                0f
            }

            // VLC balance control - set audio delay for balance effect
            // Note: VLC doesn't have direct left/right volume, so we use audio delay
            // For now, we'll just use average volume and note the limitation
            // For true independent channel control, would need AudioTrack (like Frequency Generator)

            Log.d("VLCPlayerManager", "🔊 Stereo volume - L: ${(leftVolume * 100).toInt()}%, R: ${(rightVolume * 100).toInt()}%, Balance: $balance")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error setting stereo volume", e)
        }
    }

    /**
     * Release resources
     */
    fun release() {
        try {
            mediaPlayer?.stop()
            mediaPlayer?.release()
            currentMedia?.release()
            mediaPlayer = null
            currentMedia = null
            Log.d("VLCPlayerManager", "🧹 Released VLC resources")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error releasing", e)
        }
    }

    /**
     * Release libVLC instance (call when done with manager)
     */
    fun releaseLibVLC() {
        try {
            release()
            libVLC.release()
            Log.d("VLCPlayerManager", "🧹 Released libVLC")
        } catch (e: Exception) {
            Log.e("VLCPlayerManager", "❌ Error releasing libVLC", e)
        }
    }
}

